// generated by bin/build.ts - do not edit, edit the .ts source
/**
 * Write or complete one decision in the log of the project you are standing in,
 * then re-render.
 *
 *   node /path/to/bosun/bin/save.ts --statement "..." --decision "..."
 *   node /path/to/bosun/bin/save.ts --id E27 --falsifier "..."
 *   node /path/to/bosun/bin/save.ts --log ../other-project --statement "..."
 *
 * Always saves what it was given, in the newest schema, and reports which
 * fields a complete entry is still missing. The falsifier usually arrives a
 * turn after the decision; refusing the entry until then produces invented
 * falsifiers instead of true ones. A gap is reported, wrong data is refused.
 *
 * Repeatable: --rejected "option :: because", --supersedes "E19", and
 * --supersedes-part "E23 :: what exactly was replaced".
 */

import {
  existsSync,
  mkdirSync,
  readdirSync,
  linkSync,
  readFileSync,
  rmSync,
  writeFileSync,
} from "node:fs";
import { join, basename } from "node:path";
import { spawnSync } from "node:child_process";
import { fileURLToPath } from "node:url";
import { LATEST, validate, missingFields } from "./schema.mjs";
import {
  logRoot,
  repoRoot,
  takeLog,
  sibling,
  noLogRoot,
  originOf,
  decisionsDir,
  alsoAbove,
  readEntryFile,
} from "./paths.mjs";
import { isDirectRun } from "./paths.mjs";

                                     
                                                                                 

const REPEATABLE = new Set(["rejected", "supersedes"]);

/** Ids are minted here and nowhere else, so the frozen format is enforceable. */
export const ID_FORMAT = /^\d{4}-\d{2}-\d{2}(-\d{2}){3}-\d{3}-utc$/;

/**
 * UTC timestamp with hyphens only: 2026-08-28-17-10-03-456-utc.
 *
 * Hyphens rather than ISO punctuation so the id is safe in filenames, URLs and
 * shells on every platform. The -utc suffix states the zone in the string
 * itself, so an id quoted elsewhere stays unambiguous without this schema.
 */
export function utcId(when      )         {
  return when.toISOString().replace("Z", "-utc").replaceAll(/[T:.]/g, "-");
}

export function slugify(text        )         {
  return text
    .normalize("NFC")
    .toLowerCase()
    .replaceAll("ü", "ue")
    .replaceAll("ö", "oe")
    .replaceAll("ä", "ae")
    .replaceAll("ß", "ss")
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-|-$/g, "");
}

/** --reason-type -> reason_type, repeated flags collect, --flag=value works. */
export function parseArgs(argv          )        {
  const given        = {};
  let quoteLang                    ;

  for (let i = 0; i < argv.length; i += 1) {
    const token = argv[i];
    if (!token.startsWith("--")) continue;
    const [flag, inline] = token.slice(2).split(/=(.*)/s);
    const field = flag.replaceAll("-", "_");

    let value = inline;
    if (value === undefined) {
      const next = argv[i + 1];
      // A flag swallowing the next flag is silent corruption, so refuse it.
      if (next === undefined || next.startsWith("--")) {
        throw new Error(
          `--${flag} needs a value. A value that itself starts with -- is ` +
            `written --${flag}="like this".`,
        );
      }
      value = next;
      i += 1;
    }

    if (field === "rejected") {
      const parts = value.split("::").map((part) => part.trim());
      if (parts.length !== 2 || !parts[0] || !parts[1]) {
        throw new Error(`--rejected needs "option :: because", got: ${value}`);
      }
      ((given.rejected ??= [])             ).push({
        option: parts[0],
        because: parts[1],
      });
    } else if (field === "supersedes" || field === "supersedes_part") {
      const parts = value.split("::").map((part) => part.trim());
      const whole = field === "supersedes";
      if (!whole && (parts.length !== 2 || !parts[1])) {
        throw new Error(
          `--supersedes-part needs "id :: what was replaced", got: ${value}`,
        );
      }
      ((given.supersedes ??= [])             ).push({
        id: parts[0],
        extent: whole ? "whole" : "part",
        detail: whole ? null : parts[1],
      });
    } else if (field === "quote") {
      given.quote = { text: value, lang: null };
    } else if (field === "quote_lang") {
      quoteLang = value;
    } else {
      given[field] = value;
    }
  }

  // Collected afterwards so the flags may appear in any order.
  if (given.quote) (given.quote         ).lang = quoteLang ?? "und";
  else if (quoteLang) throw new Error("--quote-lang without --quote");

  return given;
}

function defaults(origin        )        {
  return {
    alias: null,
    quote: null,
    trigger: null,
    decision: null,
    why: null,
    rejected: [],
    reason_type: null,
    implementation: null,
    consequence: null,
    falsifier: null,
    supersedes: [],
    note: null,
    provenance: null,
    origin,
    author_role: "agent",
  };
}

function readEntries(dir        )                                   {
  if (!existsSync(dir)) return [];
  // One unreadable sibling used to kill a save of an unrelated entry, because
  // the whole directory is read to pick the next alias.
  return readdirSync(dir)
    .filter((name) => name.endsWith(".json"))
    .map((name) => {
      const path = join(dir, name);
      return { path, entry: readEntryFile(path)          };
    });
}

/**
 * Resolve a reference to exactly one entry, per E107.
 *
 * An exact id or an issued E-number wins outright: what a stored link says
 * must never become ambiguous because a later filename contains it. Otherwise
 * any substring of the filename stem or the id counts, and two matches are
 * refused with both named rather than guessed between.
 */
function find(dir        , reference        ) {
  // An empty reference names everything and nothing: "".includes matched
  // every stem, and in a one-entry log it silently retired that entry.
  if (!reference.trim()) {
    throw new Error("an empty reference names everything and nothing");
  }
  const entries = readEntries(dir);
  // Exact matches are collected, not taken first-come: the same entry
  // imported twice put two files under one id, and find() quietly updated
  // whichever the directory listed first while render refused the log.
  const wanted = reference.toLowerCase();
  const exact = entries.filter(
    ({ entry }) =>
      entry.id === reference ||
      ((entry.alias          ) ?? "").toLowerCase() === wanted,
  );
  if (exact.length > 1) {
    throw new Error(
      `${exact.map(({ path }) => basename(path)).join(" and ")} both answer ` +
        `to ${reference}. Repair the log first; render names the fix.`,
    );
  }
  if (exact.length === 1) return exact[0];
  // Fragments are matched in lower case on both sides: stems and ids are
  // lower case, and "e9" skipping alias E9 into fragment matching resolved a
  // different entry than "E9" without a word.
  const matches = entries.filter(
    ({ path, entry }) =>
      basename(path, ".json").includes(wanted) ||
      ((entry.id          ) ?? "").includes(wanted),
  );
  if (matches.length > 1) {
    const shown = matches.slice(0, 5).map(({ path }) => basename(path));
    const more = matches.length - shown.length;
    throw new Error(
      `${reference} matches ${matches.length} entries: ${shown.join(", ")}` +
        (more > 0 ? ` and ${more} more` : "") + `. Say more of the name.`,
    );
  }
  return matches[0];
}

/**
 * Check that every entry this one replaces exists.
 *
 * Nothing is written on the target: who supersedes an entry is read from the
 * links, and the back-pointer that used to be stamped here held one successor
 * where an entry may have several, silently overwriting the first.
 */
                                                                              

function checkSuperseded(dir        , entry       )            {
  const targets = (entry.supersedes               ) ?? [];
  if (targets.length === 0) return [];

  const self = [entry.id, entry.alias];
  return targets.map((target) => {
    if (self.includes(target.id)) {
      throw new Error(`an entry cannot supersede itself (${target.id})`);
    }
    const hit = find(dir, target.id);
    if (!hit) throw new Error(`supersedes names an unknown entry: ${target.id}`);
    if (hit.entry.id && hit.entry.id === entry.id) {
      throw new Error(`an entry cannot supersede itself (${target.id})`);
    }
    // What reaches disk is the id, never the fragment that named it: a
    // fragment unique today is ambiguous the day a new filename contains it.
    // A target that has no id yet cannot be linked at all - skipping the
    // rewrite silently stored the fragment in the source of truth.
    if (!hit.entry.id) {
      throw new Error(
        `supersedes names ${basename(hit.path, ".json")}, which has no id ` +
          `yet. A link needs an identity; give that file its id first.`,
      );
    }
    target.id = hit.entry.id          ;
    return {
      label: (hit.entry.alias          ) ?? basename(hit.path, ".json"),
      extent: target.extent,
      statement: (hit.entry.statement          ) ?? "",
    };
  });
}

/**
 * A whole-extent link retires the target: the next fold drops its rules from
 * the compressed layer. The diff shows that to whoever reads it carefully;
 * this says it at the moment it happens, to the person doing it.
 */
function warnRetired(touched           )       {
  for (const one of touched.filter((t) => t.extent === "whole")) {
    console.error(
      `  RETIRED OUTRIGHT: ${one.label} "${one.statement}" - a whole-extent ` +
        `link removes it from the compressed layer at the next fold. If any ` +
        `of it still holds, this link is wrong: use --supersedes-part ` +
        `"${one.label} :: what exactly was replaced" instead.`,
    );
  }
}

function report(root        , entry       , path        , action        ) {
  const gaps = missingFields(entry, LATEST);
  // The short form is the stem - the date and the slug say what was decided -
  // or the E-number where one was ever issued. Both resolve as references.
  const short = (entry.alias          ) ?? basename(path, ".json");
  console.log(`${action} ${short} (${entry.id})`);
  console.log(`  ${path.slice(root.length + 1)}`);
  if (gaps.length) {
    console.log(`  still missing: ${gaps.join(", ")}`);
    console.log(
      `  complete it: node ${sibling(import.meta.url, "save")} ` +
        `--id ${short} ` +
        gaps.map((field) => `--${field.replaceAll("_", "-")} "..."`).join(" "),
    );
  } else {
    console.log("  complete");
  }
}

function refuseInvalid(entry       )          {
  const broken = validate(entry, LATEST).filter((p) => p.kind === "invalid");
  if (broken.length === 0) return false;
  console.error(`refused, schema v${LATEST}:`);
  for (const problem of broken) {
    console.error(`  ${problem.path}: ${problem.message}`);
  }
  return true;
}

export function main(argv          )         {
  try {
    return run(argv);
  } catch (error) {
    console.error("refused:", (error         ).message);
    return 1;
  }
}

function run(passed          )         {
  const { rest: argv, from } = takeLog(passed);
  // The first decision of a repository has nowhere to go yet, and refusing it
  // is how a decision gets lost: it is made once, in the minute somebody asks
  // why, and "run the installer first" is not a thing that minute survives.
  // Only inside a repository, and only at its root, because that is the one
  // place the answer is not a guess - outside one, the refusal stands.
  const root = logRoot(from) ?? repoRoot(from);
  if (!root) {
    console.error(noLogRoot(from));
    return 1;
  }
  const dir = decisionsDir(root);
  // Asked here, where the directory is still untouched, and said further down,
  // where it is actually created: announcing it up here made every refused
  // save - a mistyped --id, a bad field - claim an opening that never happened.
  const opening = !existsSync(dir);
  // Named as what it is since logs began to stack: the log above is the wider
  // project this one sits inside, not a sign of standing in the wrong place.
  // The old wording read as a warning, which after E92 tells the writer the
  // opposite of what holds - that upper log is meant to be read.
  for (const other of alsoAbove(root)) {
    // Named only where it exists: pointing a reader at a WHAT-HOLDS.md the
    // upper log has not written yet sends them to a file that is not there.
    const layer = existsSync(join(other, "WHAT-HOLDS.md"))
      ? "Read its WHAT-HOLDS.md as well; it holds in a more general form."
      : "Read it as well; what holds there is more general.";
    console.error(
      `note: ${other} holds the log of a wider project this one sits inside. ` +
        `${layer} A decision that belongs there is written there, with --log.`,
    );
  }

  let given       ;
  try {
    given = parseArgs(argv);
  } catch (error) {
    console.error((error         ).message);
    return 1;
  }

  // No handle is minted since E107, and none is edited here either: --alias
  // minted through the back door, and an alias chosen to taste hijacked
  // fragment resolution outright - exact alias wins, so --alias cache stole
  // every "cache" reference from the entry actually about caching. Files
  // from old logs keep their aliases; an import repair edits the file.
  if ("alias" in given) {
    console.error(
      "refused: --alias is not accepted. No handle is minted since E107; " +
        "for an import repair, edit the arriving file.",
    );
    return 1;
  }

  // The date comes from the same clock as the id, and the id cannot be
  // supplied either. A caller-supplied date was also a path: it reached the
  // filename unchecked, and "../../.." in it wrote outside decisions/.
  // Backdating is not lost by this - it was never allowed: nobody backfills a
  // timestamp nobody recorded. Somebody who decided yesterday says so in the
  // prose; the date records when the entry was written.
  if ("date" in given) {
    console.error(
      "refused: --date is not accepted. The date is minted from the clock, " +
        "like the id; when the decision was made belongs in the prose.",
    );
    return 1;
  }

  const reference = given.id                      ;
  const existing = reference ? find(dir, reference) : undefined;

  if (reference && !existing) {
    // Creating from a mistyped --id used to mint an entry whose id was the
    // typo, which then collided with real aliases.
    console.error(`no entry ${reference} in ${dir}`);
    return 1;
  }

  if (existing) {
    // An entry written by a newer checkout is refused, not silently stamped
    // down to this checkout's schema. Same rule as upgrade.ts.
    const held = (existing.entry.schema          ) ?? 1;
    if (held > LATEST) {
      console.error(
        `refused: ${existing.entry.alias} is schema v${held}, ` +
          `this checkout knows up to v${LATEST}`,
      );
      return 1;
    }
    // An older entry is not stamped to LATEST as it stands: that skipped the
    // migrations forever - an ISO id survived that upgrade could no longer
    // reach - and where the old shape differed, the update was refused with
    // the old data blamed, though the migration exists to convert it.
    if (held < LATEST) {
      console.error(
        `refused: ${existing.entry.alias} is schema v${held}. Run ` +
          `upgrade.mjs first, then fill the gap.`,
      );
      return 1;
    }

    const entry        = { ...existing.entry };
    for (const [key, value] of Object.entries(given)) {
      if (key === "id") continue;
      if (REPEATABLE.has(key)) {
        const held = Array.isArray(entry[key]) ? (entry[key]             ) : [];
        entry[key] = [...held, ...(value             )];
      } else {
        entry[key] = value;
      }
    }
    entry.schema = LATEST;
    if (refuseInvalid(entry)) return 1;

    let touched           ;
    try {
      touched = checkSuperseded(dir, entry);
    } catch (error) {
      console.error("refused:", (error         ).message);
      return 1;
    }

    writeFileSync(existing.path, JSON.stringify(entry, null, 2) + "\n", "utf8");
    report(root, entry, existing.path, "updated");
    if (touched.length) {
      console.log(`  superseded ${touched.map((t) => t.label).join(", ")}`);
    }
    warnRetired(touched);
    return render(root);
  }

  const statement = given.statement                      ;
  if (!statement) {
    console.error("--statement is required to create an entry");
    // The typo case: --statment lands here as an unknown field, and naming
    // only the missing flag sent the writer hunting for a flag they were sure
    // they had typed. The schema knows the stray by name; say it too.
    for (const problem of validate({ ...given, schema: LATEST }, LATEST)) {
      if (problem.kind === "invalid" && (problem.path ?? "").startsWith("entry.")) {
        console.error(`  (also: ${problem.path} ${problem.message})`);
      }
    }
    return 1;
  }

  const now = new Date();
  const entry        = {
    ...defaults(originOf(root)),
    ...given,
    schema: LATEST,
    date: now.toISOString().slice(0, 10),
    id: utcId(now),
  };

  if (!ID_FORMAT.test(entry.id          )) {
    console.error(`refused: generated id ${entry.id} is not the frozen format`);
    return 1;
  }
  if (refuseInvalid(entry)) return 1;

  // The id inherits the claim the alias had (E76, reborn): the read-check
  // alone was check-then-write, and two writers minting in the same
  // millisecond both passed it and both reported "wrote" - twelve parallel
  // saves left eleven distinct ids. An exclusive create is the same answer
  // for every process on the machine. The retry mints from a fresh clock
  // read, which is a genuinely later time, never an invented one.
  const claims = join(dir, ".ids");
  mkdirSync(claims, { recursive: true });
  const taken = new Set(
    readEntries(dir).map(({ entry: one }) => one.id          ),
  );
  for (const name of readdirSync(claims)) {
    if (taken.has(name)) rmSync(join(claims, name), { force: true });
  }
  let marker        ;
  for (;;) {
    if (!taken.has(entry.id          )) {
      marker = join(claims, entry.id          );
      try {
        writeFileSync(marker, "", { flag: "wx" });
      } catch (error) {
        if ((error                         ).code !== "EEXIST") throw error;
        const retry = new Date();
        entry.date = retry.toISOString().slice(0, 10);
        entry.id = utcId(retry);
        continue;
      }
      // Won - but confirmed against the entries, freshly: a sibling from the
      // same millisecond can win this same marker after the first winner
      // wrote its entry and cleared it. The only process that can add an
      // entry under this id after this scan is the one holding this marker.
      const burned = readEntries(dir).some(
        ({ entry: one }) => one.id === entry.id,
      );
      if (!burned) break;
      rmSync(marker, { force: true });
    }
    const again = new Date();
    entry.date = again.toISOString().slice(0, 10);
    entry.id = utcId(again);
  }

  // A statement of punctuation or non-Latin script slugifies to nothing, and
  // two of those on one day would collide on the filename.
  const slug = slugify(statement) || (entry.id          );
  const path = join(dir, `${entry.date}-${slug}.json`);
  if (existsSync(path)) {
    console.error(`refused: ${entry.date}-${slug}.json already exists`);
    return 1;
  }

  let touched           ;
  try {
    touched = checkSuperseded(dir, entry);
  } catch (error) {
    console.error("refused:", (error         ).message);
    return 1;
  }

  if (opening) console.log(`opening a log for ${root}: ${dir}`);
  mkdirSync(dir, { recursive: true });
  // Written aside and published with a hard link: a parallel save reading the
  // directory mid-write saw half a JSON and refused an unrelated entry over
  // it. The link publishes complete bytes atomically, and it cannot clobber -
  // two same-slug statements racing past the exists-check above still end
  // with one file and one clean refusal.
  const settling = join(claims, `${basename(path)}.writing`);
  writeFileSync(settling, JSON.stringify(entry, null, 2) + "\n", "utf8");
  try {
    linkSync(settling, path);
  } catch (error) {
    rmSync(settling, { force: true });
    if ((error                         ).code !== "EEXIST") throw error;
    console.error(`refused: ${basename(path)} already exists`);
    return 1;
  }
  rmSync(settling, { force: true });
  rmSync(marker, { force: true });
  report(root, entry, path, "wrote");
  if (touched.length) {
    console.log(`  superseded ${touched.map((t) => t.label).join(", ")}`);
  }
  warnRetired(touched);
  return render(root);
}

/**
 * Re-render the log that was just written, not the one the child would find.
 * Without --log the child walks up from its own working directory, which is
 * this process\'s - the same directory --log existed to overrule.
 */
function render(root        )         {
  const done = spawnSync(
    process.execPath,
    [sibling(import.meta.url, "render"), "--log", root],
    { stdio: "inherit" },
  );
  return done.status ?? 1;
}

// Only when run directly. Importing this file must not execute it.
// realpathSync on both sides: Node canonicalises import.meta.url through
// symlinks but leaves process.argv[1] as typed, so reaching a script through
// a symlinked path (/tmp on macOS, a dotfile manager, a network home) made
// every one of these silently do nothing and exit 0. A save that reports
// success and records nothing is worse than one that crashes.
if (isDirectRun(import.meta.url)) {
  process.exitCode = main(process.argv.slice(2));
}
